          "text": "세렌디피티는 단체와 기관을 운영하는 데에도 활용된다. 정보화와 세계화로 다양한 상황이 출현하고, 과거의 논리와 이성적 접근 및 합리성으로 해석되지 않는 성공사례가가 발생하다보니, 세렌디피티에 대한 관심이 전보다 더 커졌다. 페이스북을 만든 마크 주커버그는 “페이스북에는 뜻밖의 행운인 세렌디피티의 개념이 담겨 있다”고 말했다.[9] 또한 구글이 어떻게 성공했냐는 질문에 대해 구글을 만든 세르게이 브린은 “성공의 제 1요인은 행운”이라고 답했다.[10] 그렇다. 이성적인 잣대로 풀지 못하는 일들이 살피면 살필수록 더 많이 발견된다. 그렇다면, 과연 행운은 무엇인가? 우연은 무엇인가?"
