          "type": "p",
          "text": "위 그림을 보면, 위에서 아래로 내려올수록 더 보편적이다. 문화는 순환법칙으로 따지면 의미에 해당되므로, 구조론에서 문화는 의미에 해당된다. 문화는 가치와 사실의 중간단계에서 원리와 개념을 실현하는 존재이므로 사실 가장 중추적인 존재이다."
