          "text": "인식훈련은 창조의 과정에서 ‘회의(懷疑)’하는 것의 기본 토대이자 핵심 사항이다. 철학이란 학문도 결국 회의(懷疑)하는 것부터 시작한다. 영국의 철학자이며 정치가인 버트런드 러셀은 『철학의 문제들』이란 책에서 철학에 대해 명쾌하게 정의한다.[3] 철학은 ‘무엇이냐(What)’는 질문에 대답할 수 없어도, ‘왜(Why)’냐고 물을 수 있는 것이라고 했다. 무엇이냐에 대한 질문과 대답은 이미 과학에 넘겨주었기 때문이다. 철학이 할 일은 왜냐는 질문을 끊임없이 던지며 우리와 우리를 둘러싼 문제에 대하여 회의하며 성찰(reflection)하는 일이다. 철학이 이렇듯이 창조도 회의에서 출발한다. '왜'냐고 의심하는 가운데 새로운 것이 창조될 수 있다. 이처럼 회의하고 질문을 던지는 것은 능력이고, 이것은 반드시 스스로의 힘으로 몸소 익혀 자신의 것으로 만들어야 한다. 물론 마냥 ‘왜’라는 질문만 던질 순 없다.[4] ‘왜’에서 우리는 ‘어떻게’ 할 것인가를 생각해 보아야한다. ‘왜’라는 질문과 ‘어떻게’라는 구체적 행동이 결합되었을 때, 하나의 가시적인 창조물이 나올 수 있다."
