          "text": "앞에서 제주도를 자연, 사랑과 행운, 창조성, 과학, 문화에 입각하여 알아보았다. 이 가운데 제주문화의 특징적 요소로서 새롭게 제시할 수 있는 것은 자연, 사랑, 도덕 그리고 행운이다."
